const body = $('Webhook Trigger').item.json.body || {};
const registryData = $input.item.json || {};
const registry = registryData.departments || [];
const packs = registryData.packs || {};

const campaignContract = body.campaign_contract && typeof body.campaign_contract === 'object' ? body.campaign_contract : null;

if (!campaignContract || typeof campaignContract.campaign_brief !== 'string' || !campaignContract.campaign_brief.trim() || campaignContract.campaign_duration_days === undefined || campaignContract.paid_media_allowed === undefined || !Array.isArray(campaignContract.required_terms)) {
  return { json: { valid: false, reason: 'Thiếu campaign_contract hoặc contract thiếu field bắt buộc (campaign_duration_days, paid_media_allowed, required_terms).' } };
}

const campaignBrief = campaignContract.campaign_brief;
const campaignGoal = campaignContract.campaign_goal || '';
const campaignDurationDays = campaignContract.campaign_duration_days;
const paidMediaAllowed = campaignContract.paid_media_allowed;
const requiredTerms = campaignContract.required_terms;
const targetTerms = Array.isArray(campaignContract.target_terms) ? campaignContract.target_terms : requiredTerms;
const validationHints = Array.isArray(campaignContract.validation_hints) ? campaignContract.validation_hints : [];

const envelopeBrief = typeof body.campaign_brief === 'string' ? body.campaign_brief : (typeof body.body === 'string' ? body.body : '');
const envelopeGoal = typeof body.campaign_goal === 'string' ? body.campaign_goal : '';
const envelopeDurationDays = Number.isInteger(body.campaign_duration_days) ? body.campaign_duration_days : null;
const envelopePaidMediaAllowed = body.paid_media_allowed === true ? true : body.paid_media_allowed === false ? false : null;

const contractMismatch = (
  (envelopeBrief !== '' && envelopeBrief !== campaignBrief) ||
  (envelopeGoal !== '' && envelopeGoal !== campaignGoal) ||
  (envelopeDurationDays !== null && envelopeDurationDays !== campaignDurationDays) ||
  (envelopePaidMediaAllowed !== null && envelopePaidMediaAllowed !== paidMediaAllowed)
);

if (contractMismatch) {
  return { json: { valid: false, reason: 'Campaign contract mismatch between control plane envelope and resolved contract' } };
}

if (!body.organization_id || !body.thread_id) {
  return { json: { valid: false, reason: 'Thiếu thông tin thread_id hoặc organization_id' } };
}

let matchedDept = null;
if (body.department_id) {
  matchedDept = registry.find(d => d.department_id === body.department_id);
} else if (body.department_name) {
  matchedDept = registry.find(d => d.department_name === body.department_name);
}

if (!matchedDept) {
  return { json: { valid: false, reason: 'Department not found in registry (Phòng ban chưa được cấp phép)' } };
}

const packKey = matchedDept.department_pack_key;
if (!packKey) {
  return { json: { valid: false, reason: 'Backend API did not resolve department_pack_key for this department' } };
}

const departmentPack = packs[packKey] || {};
if (Object.keys(departmentPack).length === 0) {
  return { json: { valid: false, reason: 'Department Pack payload is missing or empty' } };
}

return { 
  json: { 
    valid: true, 
    thread_id: body.thread_id,
    organization_id: body.organization_id,
    body: campaignBrief,
    campaign_brief: campaignBrief,
    campaign_goal: campaignGoal || campaignBrief,
    campaign_duration_days: campaignDurationDays,
    paid_media_allowed: paidMediaAllowed,
    target_terms: targetTerms,
    required_terms: requiredTerms,
    validation_hints: validationHints,
    campaign_contract: campaignContract,
    department_id: matchedDept.department_id, 
    department_name: matchedDept.department_name,
    department_pack: departmentPack,
    department_pack_key: packKey,
    department_pack_label: matchedDept.department_pack || ''
  } 
};

