const response = $input.item.json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  throw new Error('STRUCTURAL_ERROR: Agent 1 did not return valid JSON.');
}

if (!parsed.daily_timeline || typeof parsed.daily_timeline !== 'object') {
  throw new Error('STRUCTURAL_ERROR: Agent 1 output is missing or invalid `daily_timeline`. Must be an object or array.');
}

const needsClarification = parsed.needs_clarification === true;
const clarificationQuestions = Array.isArray(parsed.clarification_questions)
  ? parsed.clarification_questions.filter((question) => typeof question === 'string' && question.trim())
  : [];

if (needsClarification) {
  return {
    json: {
      ...$input.item.json,
      needs_clarification: true,
      clarification_questions: clarificationQuestions,
      reason: typeof parsed.reason === 'string' && parsed.reason.trim()
        ? parsed.reason
        : 'NEEDS_CLARIFICATION'
    }
  };
}

const scope = $node['Scope Resolve'].json;
const contract = scope.campaign_contract || {};
const requiredTerms = Array.isArray(contract.required_terms) ? contract.required_terms.filter((term) => typeof term === 'string' && term.trim()) : [];
const paidMediaAllowed = contract.paid_media_allowed;
const normalizedPacket = JSON.stringify(parsed).toLowerCase();

if (Number.isInteger(contract.campaign_duration_days)) {
  const expectedDays = contract.campaign_duration_days;
  const timelineKeys = Object.keys(parsed.daily_timeline);
  const timelineLength = Array.isArray(parsed.daily_timeline) ? parsed.daily_timeline.length : timelineKeys.length;
  if (timelineLength !== expectedDays) {
    throw new Error('VALIDATION_ERROR: Agent 1 output failed strict contract. Expected exactly ' + expectedDays + ' days from deterministic contract, but got ' + timelineLength + ' days.');
  }
}

if (paidMediaAllowed === false && parsed.uses_ads !== false) {
  throw new Error('VALIDATION_ERROR: Agent 1 output failed strict contract. Strategy uses ads despite paid_media_allowed=false.');
}

for (const term of requiredTerms) {
  const normalizedTerm = term.toLowerCase().trim();
  if (normalizedTerm && !normalizedPacket.includes(normalizedTerm)) {
    throw new Error('VALIDATION_ERROR: Agent 1 output failed deterministic required_terms check. Missing term: ' + term);
  }
}

if (typeof contract.campaign_goal === 'string' && contract.campaign_goal.trim()) {
  const goalTokens = contract.campaign_goal.toLowerCase().split(/\s+/).filter(Boolean).slice(0, 3);
  if (goalTokens.length > 0 && !goalTokens.every((token) => normalizedPacket.includes(token))) {
    throw new Error('VALIDATION_ERROR: Agent 1 output is not sufficiently anchored to campaign_goal from contract.');
  }
}

return {
  json: {
    ...$input.item.json,
    needs_clarification: false,
    clarification_questions: []
  }
};

